        private async Task LoadScriptsAsync()
        {
            if (MyWebView.CoreWebView2 == null)
            {
                return;
            }

            var scriptFile = await StorageFile.GetFileFromApplicationUriAsync(new Uri("ms-appx:///scripts.js"));
            var scriptContent = await FileIO.ReadTextAsync(scriptFile);
            await MyWebView.CoreWebView2.AddScriptToExecuteOnDocumentCreatedAsync(scriptContent);
        }

        private Task SendBytesToPageAsync()
        {
            if (MyWebView.CoreWebView2 == null)
                return Task.CompletedTask;

            // Lazily create the shared-buffer manager once per process (all windows share it).
            lock (_managerLock)
            {
                _bufferManager ??= new SharedBufferManager(MyWebView.CoreWebView2.Environment);
            }

            // Allocate a 1 MB segment from whichever slab has free capacity
            // (a new slab is created automatically if needed, up to the 2 GB limit).
            SegmentHandle handle = _bufferManager.AllocateSegment(_windowId);
            if (!handle.IsValid)
            {
                LogAction("ERROR: No free shared-buffer segment available (2 GB pool exhausted).");
                return Task.CompletedTask;
            }

            _segmentHandle = handle;

            ulong segmentOffset = SharedBufferManager.ContentOffset(handle);
            ulong segmentSize   = SharedBufferManager.ContentSize;

            Debug.WriteLine(
                $"[{_windowId}] Allocated slab={handle.SlabIndex} seg={handle.SegmentIndex}: " +
                $"offset={segmentOffset}, size={segmentSize}");
            LogAction(
                $"Slab={handle.SlabIndex} Seg={handle.SegmentIndex} allocated " +
                $"(offset={segmentOffset}, contentSize={segmentSize}, windowId={_windowId})");

            // Post ONLY the slab buffer that owns this window's segment.
            // JS receives a view of that slab's SharedArrayBuffer and uses
            // segmentOffset to find its 1 MB slice within it.
            string additionalDataAsJson =
                System.Text.Json.JsonSerializer.Serialize(new
                {
                    type          = "init",
                    windowId      = _windowId,
                    slabIndex     = handle.SlabIndex,
                    segmentIndex  = handle.SegmentIndex,
                    segmentOffset = (long)segmentOffset,
                    segmentSize   = (long)segmentSize
                });

            MyWebView.CoreWebView2.PostSharedBufferToScript(
                _bufferManager.GetSlabBuffer(handle),
                CoreWebView2SharedBufferAccess.ReadWrite,
                additionalDataAsJson);

            // Update the UI badge.
            SegmentInfoText.Text =
                $"Slab {handle.SlabIndex}  Seg {handle.SegmentIndex}  |  " +
                $"offset={segmentOffset}  |  contentSize={segmentSize} B  |  id={_windowId[..8]}";

            return Task.CompletedTask;
        }

        private void ReleaseWindow()
        {
            if (_bufferManager == null || _segmentHandle is not { IsValid: true } handle)
                return;

            LogAction($"Window closing – releasing slab={handle.SlabIndex} seg={handle.SegmentIndex} (windowId={_windowId})");
            _bufferManager.ReleaseSegment(_windowId);
            _segmentHandle = null;
        }

        private void NewWindow_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
        {
            var newWindow = new MainWindow();
            newWindow.Activate();
            LogAction($"Opened new window. Active windows now share the same 5 MB pool.");
        }

        private void SetupActionLogging()
        {
            if (MyWebView.CoreWebView2 == null) return;

            double elapsed = 0;
            // Listen for messages from JavaScript
            MyWebView.CoreWebView2.WebMessageReceived += async (s, e) =>
            {
                try
                {
                    var json = e.TryGetWebMessageAsString();
                    if (string.IsNullOrEmpty(json))
                    {
                        LogAction("Received empty or non-string web message, skipping.");
                        return;
                    }

                    // Try parsing as JSON object
                    System.Text.Json.JsonDocument obj;
                    try
                    {
                        obj = System.Text.Json.JsonDocument.Parse(json);
                    }
                    catch
                    {
                        // Not a JSON message (e.g. plain string from tracking scripts)
                        LogAction($"JS Event: {json}");
                        return;
                    }

                    if (!obj.RootElement.TryGetProperty("type", out var typeProp))
                    {
                        LogAction($"JS message without type: {json}");
                        return;
                    }

                    var messageType = typeProp.GetString();
                    double readDuration = 0;
                    double encodingDuration = 0;
                    if (messageType == "fullContentReady")
                    {
                        if (_bufferManager == null || _segmentHandle is not { IsValid: true } handle)
                        {
                            LogAction("ERROR: Shared buffer / segment not initialized");
                            return;
                        }

                        // Cross-check: verify the segment still belongs to this window.
                        if (!_bufferManager.VerifyWindowId(handle, _windowId))
                        {
                            LogAction($"ERROR: Slab={handle.SlabIndex} Seg={handle.SegmentIndex} cross-check failed – aborting read.");
                            return;
                        }

                        obj.RootElement.TryGetProperty("bytes", out var sizeProp);
                        int byteCount = sizeProp.GetInt32();

                        var startRead = DateTime.Now;
                        byte[] buffer = _bufferManager.ReadSegmentContent(handle, byteCount);
                        var endRead = DateTime.Now;
                        readDuration = (endRead - startRead).TotalMilliseconds;

                        var startEncoding = DateTime.Now;
                        string content = Encoding.UTF8.GetString(buffer);
                        var endEncoding = DateTime.Now;
                        encodingDuration = (endEncoding - startEncoding).TotalMilliseconds;
                        Save.Foreground = new SolidColorBrush(Colors.Red);
                    }
                    else if (messageType == "userInput")
                    {
                        LogAction("User input detected in editor");
                    }
                    if (!obj.RootElement.TryGetProperty("time", out var timeProp))
                    {
                        LogAction($"JS message without time: {json}");
                        return;
                    }
                    else
                    {
                        //var timestamp = timeProp.GetDouble();
                        //var totaltime = timestamp + elapsed;
                        //LogAction($"Script execution result: {timestamp} ms total time with WR: {totaltime}ms");

                        LogAction($"Write duration : {timeProp} ms");
                        LogAction($"Read duration : {readDuration} ms");
                        LogAction($"Encoding duration : {encodingDuration} ms");
                        LogAction("--------------------------------------------------");
                    }
                }
                catch (Exception ex)
                {
                    LogAction($"ERROR processing web message: {ex.Message}");
                }
            };

            MyWebView.CoreWebView2.DOMContentLoaded += async (s, e) =>
            {
                string trackingScript = @"
                    (function() {
                        // Track mouse clicks
                        document.addEventListener('click', function(e) {
                            window.chrome.webview.postMessage('CLICK: ' + e.target.tagName + ' at (' + e.clientX + ',' + e.clientY + ')');
                        });

                        // Track key presses
                        document.addEventListener('keydown', function(e) {
                            window.chrome.webview.postMessage('KEYDOWN: ' + e.key + ' (code: ' + e.code + ')');
                        });

                        // Track focus events
                        document.addEventListener('focus', function(e) {
                            window.chrome.webview.postMessage('FOCUS: ' + e.target.tagName);
                        }, true);

                        // Track blur events
                        document.addEventListener('blur', function(e) {
                            window.chrome.webview.postMessage('BLUR: ' + e.target.tagName);
                        }, true);

                        // Track selection changes
                        document.addEventListener('selectionchange', function() {
                            var selection = window.getSelection();
                            if (selection.toString().length > 0) {
                                window.chrome.webview.postMessage('SELECTION: ' + selection.toString().substring(0, 50));
                            }
                        });

                        // Track scroll events (throttled)
                        let scrollTimeout;
                        document.addEventListener('scroll', function(e) {
                            clearTimeout(scrollTimeout);
                            scrollTimeout = setTimeout(function() {
                                window.chrome.webview.postMessage('SCROLL: scrollY=' + window.scrollY);
                            }, 200);
                        }, true);

                        // Track input events for contenteditable
                        document.addEventListener('input', function(e) {
                            window.chrome.webview.postMessage('INPUT: ' + e.target.tagName + ' - ' + e.inputType);
                        });

                        window.chrome.webview.postMessage('Action tracking initialized');
                    })();
                ";
                string perfScript = @"
                    (function() {
                        const post = (kind, detail, startedAt) => {
                            const elapsed = performance.now() - startedAt;
                            window.chrome.webview.postMessage(`PERF:${kind}:${detail}:${elapsed.toFixed(2)}ms`);
                        };

                        //// Typing latency: keydown -> next frame
                        //document.addEventListener('keydown', e => {
                        //    const start = performance.now();
                        //    requestAnimationFrame(() => post('TYPE', e.key, start));
                        //}, true);

                        //// Paste latency: paste -> 2nd frame (content committed)
                        //document.addEventListener('paste', () => {
                        //    const start = performance.now();
                        //    requestAnimationFrame(() => requestAnimationFrame(() => post('PASTE', 'content', start)));
                        //}, true);

                        //// Selection latency: selectionchange -> next frame
                        //document.addEventListener('selectionchange', () => {
                        //    const start = performance.now();
                        //    requestAnimationFrame(() => post('SELECT', 'selection', start));
                        //}, true);

                        // Scroll latency: scroll -> next frame (throttled)
                        let scrollScheduled = false;
                        document.addEventListener('scroll', () => {
                            if (scrollScheduled) return;
                            scrollScheduled = true;
                            const start = performance.now();
                            requestAnimationFrame(() => {
                                scrollScheduled = false;
                                post('SCROLL', `scrollY=${Math.round(window.scrollY)}`, start);
                            });
                        }, { passive: true, capture: true });

                        window.chrome.webview.postMessage('Performance tracking initialized');
                    })();
                ";

                await MyWebView.CoreWebView2.ExecuteScriptAsync(trackingScript);
                //await MyWebView.CoreWebView2.ExecuteScriptAsync(perfScript);
                LogAction("Action tracking script injected");
            };
        }

        private void MyWebView_CoreWebView2Initialized(WebView2 sender, CoreWebView2InitializedEventArgs args)
        {
            if (args.Exception != null)
            {
                LogAction($"ERROR: CoreWebView2Initialized with exception: {args.Exception.Message}");
            }
            else
            {
                LogAction($"CoreWebView2Initialized successfully. Browser version: {sender.CoreWebView2?.Environment?.BrowserVersionString}");
            }
        }

        private void WebView2DiagnosticEvents()
        {
            if (MyWebView.CoreWebView2 == null)
            {
                LogAction("WARNING: CoreWebView2 is null, cannot setup diagnostic events");
                return;
            }

            var coreWebView = MyWebView.CoreWebView2;

            coreWebView.ProcessFailed += (s, e) =>
            {
                LogAction($"PROCESS FAILED - Kind: {e.ProcessFailedKind}, Reason: {e.Reason}, Exit code: {e.ExitCode}, Process: {e.ProcessDescription}");
            };

            // Navigation events
            coreWebView.NavigationStarting += (s, e) =>
            {
                LogAction($"NAV Starting: .......");
            };

            coreWebView.NavigationCompleted += async (s, e) =>
            {
                LogAction($"NAV Completed - Success: {e.IsSuccess}, Status: {e.WebErrorStatus}");
                MyWebView.CoreWebView2.OpenDevToolsWindow();
                if (!_sharedBufferPosted && e.IsSuccess)
                {
                    _sharedBufferPosted = true;
                    await SendBytesToPageAsync();
                }

            };

            // Content loading events
            coreWebView.ContentLoading += (s, e) =>
            {
                LogAction("Content loading");
            };

            coreWebView.DOMContentLoaded += (s, e) =>
            {
                LogAction("DOM content loaded");
            };
            LogAction("Diagnostic events setup complete");
        }

        private void Click_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
        {
            LogAction("WinUI Button clicked");
            if ((ClickButton.Background as SolidColorBrush)?.Color == Colors.LightBlue)
            {
                ClickButton.Background = new SolidColorBrush(Colors.LightGreen);
            }
            else
            {
                ClickButton.Background = new SolidColorBrush(Colors.LightBlue);
            }
        }

        private async void Save_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
        {
            LogAction("Save button clicked - attempting to execute sendFullContent");
            try
            {
                if (MyWebView?.CoreWebView2 == null)
                {
                    LogAction("ERROR: WebView2 is not initialized");
                    return;
                }

                await MyWebView.ExecuteScriptAsync("onSaveButtonClick();");
                var result = await MyWebView.ExecuteScriptAsync("sendFullContent();");
                //LogAction($"Script execution result: {result}");
            }
            catch (Exception ex)
            {
                LogAction($"Error executing script: {ex.Message}");
            }
        }
    }
